import{_ as o,C as t,o as s,c as r,E as a,a2 as l}from"./chunks/framework.BOeh4kYD.js";const c="/joinwell52/assets/figures/miit-209-ai-software-policy/en/01-policy-roles.png",d="/joinwell52/assets/figures/miit-209-ai-software-policy/en/02-policy-targets.png",p="/joinwell52/assets/figures/miit-209-ai-software-policy/en/03-agent-industry.png",u="/joinwell52/assets/figures/miit-209-ai-software-policy/en/04-verifiable-behavior.png",h="/joinwell52/assets/figures/miit-209-ai-software-policy/en/05-software-value-chain.png",m="/joinwell52/assets/figures/miit-209-ai-software-policy/en/06-enterprise-paths.png",g="/joinwell52/assets/figures/miit-209-ai-software-policy/en/07-transformation-roadmap.png",A=JSON.parse(`{"title":"MIIT Document No. 209 Explained: Agent Software and the Transformation of the Software Industry","description":"","frontmatter":{"title":"MIIT Document No. 209 Explained: Agent Software and the Transformation of the Software Industry","date":"2026-09-15","language":"en","article_type":"policy-analysis","summary":"MIIT's AI Plus Software plan reshapes software production, agent products and ongoing services. It sets out execution frameworks, Skills markets, standards and verifiable behavior, with practical implications for software-company transformation.","publication_authorized":true,"lifecycle":"Published","column":"industry-architecture","category":"daily","edition":"research-center","cover":"/assets/covers/miit-209-ai-software-policy.png"},"headers":[],"relativePath":"en/industry/2026-09-15-miit-209-ai-software-policy.md","filePath":"en/industry/2026-09-15-miit-209-ai-software-policy.md","lastUpdated":1789534935000}`),f={name:"en/industry/2026-09-15-miit-209-ai-software-policy.md"};function w(b,e,y,v,k,I){const n=t("ArticleCover"),i=t("ArticleTableScroll");return s(),r("div",null,[a(n,{image:"/assets/covers/miit-209-ai-software-policy.png",kicker:"Industry Architecture · Policy Analysis",title:"MIIT Document No. 209 Explained: Agent Software and the Transformation of the Software Industry",summary:"MIIT's AI Plus Software plan reshapes software production, agent products and ongoing services. It sets out execution frameworks, Skills markets, standards and verifiable behavior, with practical implications for software-company transformation.",version:"2026-09-15",languageHref:"/zh/industry/2026-09-15-miit-209-ai-software-policy",languageLabel:"中文版"}),a(i,{language:"en"}),e[0]||(e[0]=l('<h1 id="miit-document-no-209-explained-agent-software-and-the-transformation-of-the-software-industry" tabindex="-1">MIIT Document No. 209 Explained: Agent Software and the Transformation of the Software Industry <a class="header-anchor" href="#miit-document-no-209-explained-agent-software-and-the-transformation-of-the-software-industry" aria-label="Permalink to &quot;MIIT Document No. 209 Explained: Agent Software and the Transformation of the Software Industry&quot;">​</a></h1><p>On September 11, 2026, China&#39;s Ministry of Industry and Information Technology (MIIT) published the <a href="https://www.miit.gov.cn/jgsj/xxjsfzs/wjfb/art/2026/art_91a26793271e4c77aca49ecde4472999.html" target="_blank" rel="noreferrer">Implementation Plan for the “AI Plus Software” Special Action</a>. Numbered Gong Xin Bu Xin Fa [2026] No. 209 and dated September 2, the document was issued to industry and information technology authorities in all provinces, autonomous regions, municipalities and the Xinjiang Production and Construction Corps, asking them to implement it in light of local conditions.</p><p>The title might suggest a simple call for software companies to use more AI. But the eight-page plan and its 19 tasks address much more than AI-assisted coding.</p><p>The document tackles three fundamental questions for the software industry.</p><p>First, how will software be produced?</p><p>Second, what will software itself become?</p><p>Third, when software starts acting continuously as an agent, who will provide the execution frameworks, skills, markets, standards, security and boundaries of responsibility?</p><p>Document No. 209 therefore matters for more than adding another “AI Plus” policy. China is beginning to organize <strong>intelligent programming, agent software and intelligent services</strong> as new growth drivers for the software industry. Agents, previously often grouped together with large models, chatbots and automation tools, now sit within a complete software value chain: development tools, execution frameworks, software products, skill packages, application marketplaces, delivery services, and standards for identity, interfaces, behavior and security.</p><p>Agents are moving from a model feature toward a distinct form of software.</p><aside class="policy-keywords" aria-label="Six terms for understanding Document No. 209"><p class="policy-keywords-title"><strong>Understanding Document No. 209 in Six Terms</strong></p><div class="policy-keywords-grid"><div><strong>Intelligent programming</strong><span>Transform software production</span></div><div><strong>Intelligent companions</strong><span>Upgrade existing software</span></div><div><strong>Agent software</strong><span>Develop new product forms</span></div><div><strong>Skills</strong><span>Package specialist capabilities</span></div><div><strong>Intelligent services</strong><span>Deliver value continuously</span></div><div><strong>Verifiable behavior</strong><span>Inspect execution and outcomes</span></div></div></aside><h2 id="i-beyond-document-no-414-adding-products-and-infrastructure" tabindex="-1">I. Beyond Document No. 414: Adding Products and Infrastructure <a class="header-anchor" href="#i-beyond-document-no-414-adding-products-and-infrastructure" aria-label="Permalink to &quot;I. Beyond Document No. 414: Adding Products and Infrastructure&quot;">​</a></h2><p>To understand Document No. 209, it helps to place it in the sequence of policies released in 2026, without treating the documents as interchangeable.</p><p><a href="https://www.miit.gov.cn/jgsj/kjs/wjfb/art/2026/art_331b6f1d28ad410aa9df711acf42dbfe.html" target="_blank" rel="noreferrer">Document No. 414</a>, published on August 31, organizes a resource pool, service teams, real use cases, delivery arrangements and ongoing evaluation around AI application service providers. Its question is: <strong>who brings AI into enterprises, and who takes responsibility for consulting, implementation, operations and security governance?</strong></p><p>The <a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">Artificial Intelligence SME Entrepreneurship Support Plan (2026–2028)</a>, published on September 4, brings AI-native firms, agent developers, open-source contributors, “one-person companies” and highly capable individual entrepreneurs into the scope of startup support. Its question is: <strong>who starts new AI businesses, and how will the computing, data, use cases, capital and services they need become available?</strong></p><p>We analyzed those documents in <a href="https://joinwell52-ai.github.io/joinwell52/en/industry/2026-09-04-miit-414-ai-application-delivery" target="_blank" rel="noreferrer">MIIT Document No. 414 Explained: From Model Supply to Application Delivery</a> and <a href="https://joinwell52-ai.github.io/joinwell52/en/industry/2026-09-08-miit-ai-sme-support-plan" target="_blank" rel="noreferrer">MIIT&#39;s AI SME Entrepreneurship Support Plan Explained: An AI Startup Ecosystem Is Taking Shape</a>.</p><p>Document No. 209 addresses a third question:</p><blockquote><p>What software will these entrepreneurs and service providers actually produce, run and deliver?</p></blockquote><p>It takes policy further inside the software industry. From production tools, technical foundations, product forms and service models to open source, computing, data, standards, talent and security, it offers a more complete plan for building the industry.</p><p>The three documents have distinct roles:</p><table tabindex="0"><thead><tr><th>Document</th><th>Main subject</th><th>Central question</th></tr></thead><tbody><tr><td>Document No. 414</td><td>AI application service providers</td><td>Who handles consulting, integration, delivery, operations and governance?</td></tr><tr><td>Entrepreneurship Support Plan</td><td>AI SMEs and entrepreneurs</td><td>Who starts businesses, and how do they obtain computing, data, use cases and capital?</td></tr><tr><td>Document No. 209</td><td>Software and information technology services</td><td>How is next-generation software produced, how does it run, and what industrial foundations does it need?</td></tr></tbody></table><p>If Document No. 414 organizes the delivery teams and the entrepreneurship plan cultivates new companies, Document No. 209 defines the software industry system they will help build.</p><p><img src="'+c+'" alt="The three policies address delivery providers, startup support and the software industry: distinct but complementary roles."></p><p><em>Figure 1. The three policies address delivery providers, startup support and the software industry: distinct but complementary roles. Source: Relevant MIIT policy documents; compiled by the author.</em></p><h2 id="ii-why-ai-plus-software-means-more-than-adding-ai-to-software" tabindex="-1">II. Why “AI Plus Software” Means More Than Adding AI to Software <a class="header-anchor" href="#ii-why-ai-plus-software-means-more-than-adding-ai-to-software" aria-label="Permalink to &quot;II. Why “AI Plus Software” Means More Than Adding AI to Software&quot;">​</a></h2><p>The opening of the document identifies three things AI is changing: <strong>development methods, product forms and service models</strong>.</p><p>Each represents a different transformation.</p><h3 id="the-first-transformation-how-software-is-produced" tabindex="-1">The first transformation: how software is produced <a class="header-anchor" href="#the-first-transformation-how-software-is-produced" aria-label="Permalink to &quot;The first transformation: how software is produced&quot;">​</a></h3><p>AI will no longer be merely a completion tool used while a programmer writes a piece of code. It will participate throughout a project: understanding requirements, designing architecture, coding, testing, checking security, deployment, operations and ongoing changes.</p><p>The plan therefore calls for agent-driven intelligent programming tools, stronger project-level autonomous development across the full process, and deeper integration with code hosting platforms, cloud services and open-source communities. The relevant unit is no longer how quickly a function can be written, but whether an entire software project can be completed more efficiently and reliably.</p><p>This also explains the call for intelligent upgrading within software companies. Genuine upgrading means more than installing a chat plugin for every programmer. It requires redesigning development processes, quality control, security checks and collaboration, with results assessed through code quality, development effectiveness and other practical outcomes.</p><h3 id="the-second-transformation-what-a-software-product-is" tabindex="-1">The second transformation: what a software product is <a class="header-anchor" href="#the-second-transformation-what-a-software-product-is" aria-label="Permalink to &quot;The second transformation: what a software product is&quot;">​</a></h3><p>Traditional software mainly waits for users to click menus, fill in forms and issue commands. Agent software can receive goals, understand its environment, select tools, execute successive steps and adjust subsequent actions based on results.</p><p>The document therefore treats agent software as a new product form in its own right, rather than discussing only AI features added to existing software. It covers capabilities embedded in operating systems, databases, industrial software and devices, as well as general-purpose agents, specialist industry agents and industrial agents.</p><p>This raises the agent from an interface feature to a software product category.</p><h3 id="the-third-transformation-how-software-services-work" tabindex="-1">The third transformation: how software services work <a class="header-anchor" href="#the-third-transformation-how-software-services-work" aria-label="Permalink to &quot;The third transformation: how software services work&quot;">​</a></h3><p>Traditional software services tend to revolve around licenses, implementation projects and maintenance. Intelligent software services may instead become a continuously operating service chain: models keep changing, knowledge is updated, agents keep executing, permissions and costs evolve, and results need ongoing verification.</p><p>The plan calls for an end-to-end intelligent application service chain, encourages software firms to become AI application service providers, and promotes a shift from one-off delivery to ongoing service and value delivery.</p><p>Together, these three changes express the full meaning of “AI Plus Software”: AI is reorganizing software production, products and business models.</p><h2 id="iii-2028-and-2030-from-adoption-at-scale-to-industry-upgrading" tabindex="-1">III. 2028 and 2030: From Adoption at Scale to Industry Upgrading <a class="header-anchor" href="#iii-2028-and-2030-from-adoption-at-scale-to-industry-upgrading" aria-label="Permalink to &quot;III. 2028 and 2030: From Adoption at Scale to Industry Upgrading&quot;">​</a></h2><p>Document No. 209 sets two stages of objectives.</p><p>By 2028:</p><ul><li>Intelligent programming tools and intelligent development platforms should reach 20,000 software enterprises above the designated size.</li><li>A total of 100 intelligent upgrading projects should be implemented in software companies.</li><li>Priority industries should develop 100 benchmark agent software applications.</li><li>At least 15 hardware–software adaptation centers should be established.</li><li>At least five high-quality open-source projects should be incubated.</li></ul><p>By 2030:</p><ul><li>Key software should have undergone comprehensive intelligent upgrading.</li><li>Intelligent programming, agent software and intelligent services should become new industry growth drivers.</li><li>A number of internationally influential open-source communities and industry clusters should be established.</li></ul><p>These figures should not simply be added together: each serves a different policy purpose.</p><p>Reaching 20,000 companies measures diffusion of production tools. The 100 upgrading projects are meant to produce reusable examples of company transformation. The 100 benchmark agent applications test whether new products can enter real industries. Adaptation centers support hardware–software coordination and industrial validation. Open-source projects contribute to a shared technical ecosystem.</p><p>The plan is therefore building adoption at scale, demonstration projects, validation facilities and open-source foundations at the same time.</p><p>Read together, the targets emphasize adoption and validation at scale by 2028, followed by upgrading key software, growing new business forms, and developing internationally influential open-source communities and industry clusters by 2030. They describe a policy path from broader adoption toward industry upgrading, rather than suggesting that the industry&#39;s structure will be settled by then.</p><p><img src="'+d+'" alt="The 2028 targets cover firms, projects, applications, compatibility centers and open source; 2030 points toward industry transformation."></p><p><em>Figure 2. The 2028 targets cover firms, projects, applications, compatibility centers and open source; 2030 points toward industry transformation. Source: Relevant MIIT policy documents; compiled by the author.</em></p><h3 id="agents-are-a-new-growth-area-but-document-no-209-is-not-an-agent-only-policy" tabindex="-1">Agents Are a New Growth Area, but Document No. 209 Is Not an Agent-Only Policy <a class="header-anchor" href="#agents-are-a-new-growth-area-but-document-no-209-is-not-an-agent-only-policy" aria-label="Permalink to &quot;Agents Are a New Growth Area, but Document No. 209 Is Not an Agent-Only Policy&quot;">​</a></h3><p>The <a href="https://www.miit.gov.cn/jgsj/xxjsfzs/wjfb/art/2026/art_91a26793271e4c77aca49ecde4472999.html" target="_blank" rel="noreferrer">implementation plan</a> also addresses intelligent upgrading of foundational and industrial software itself. Operating systems and databases are to improve agent scheduling, performance tuning, operations and security, with chip and server manufacturers collaborating on hardware–software compatibility and adaptation centers. Industrial software such as CAD, CAE and EDA is to apply AI to drawing, design and simulation, while industrial internet platforms strengthen data analysis, production scheduling and multi-agent decision-making.</p><p>Document No. 209 should therefore be read as combining upgrades to existing software with the development of new software forms. Foundational software, industrial software and development methods all need intelligent upgrading. Agents are an important emerging form within that broader software-industry transformation.</p><h2 id="iv-the-most-consequential-new-concept-is-agent-software" tabindex="-1">IV. The Most Consequential New Concept Is Agent Software <a class="header-anchor" href="#iv-the-most-consequential-new-concept-is-agent-software" aria-label="Permalink to &quot;IV. The Most Consequential New Concept Is Agent Software&quot;">​</a></h2><p>Intelligent programming matters: it directly affects software production efficiency and can scale relatively quickly. From an industry-structure perspective, however, the most notable part of Document No. 209 is its fourth section, on <strong>cultivating new forms of agent software and accelerating their continuous evolution</strong>.</p><p>It introduces at least four layers.</p><h3 id="_1-agent-execution-frameworks" tabindex="-1">1. Agent execution frameworks <a class="header-anchor" href="#_1-agent-execution-frameworks" aria-label="Permalink to &quot;1. Agent execution frameworks&quot;">​</a></h3><p>The plan calls for engineering research into agent execution frameworks, improving reliable execution of complex tasks and collaboration among multiple agents.</p><p>The emphasis on execution frameworks shows attention to engineering foundations beyond models. <strong>From an enterprise engineering perspective,</strong> a large model can generate an answer, but it does not automatically solve persistent state, tool use, permission constraints, failure recovery, concurrency conflicts, handoffs and acceptance of results over a long-running task. These are engineering questions the author derives from reliable execution and multi-agent collaboration, not a feature checklist prescribed item by item in the document.</p><h3 id="_2-agent-software-development-platforms" tabindex="-1">2. Agent software development platforms <a class="header-anchor" href="#_2-agent-software-development-platforms" aria-label="Permalink to &quot;2. Agent software development platforms&quot;">​</a></h3><p>The document proposes agent software development platforms and better toolchains for development, testing, deployment and operations.</p><p>Agent development cannot remain a collection of prompts, demonstration pages and temporary scripts. Like mature software, it needs design, testing, releases, monitoring, upgrades and maintenance, supported by repeatable engineering processes.</p><h3 id="_3-agent-software-products" tabindex="-1">3. Agent software products <a class="header-anchor" href="#_3-agent-software-products" aria-label="Permalink to &quot;3. Agent software products&quot;">​</a></h3><p>The plan separately addresses general-purpose agents, device agents, specialist agents for vertical domains and industrial agents. Each category brings different reliability and accountability requirements.</p><p>An office information-processing agent can work under human review. Device agents need lightweight inference and privacy protection. Vertical-domain agents need knowledge graphs and industry data. Industrial agents may enter core production processes and interact with industrial control systems and critical business systems. They therefore require greater safety, reliability and verifiable behavior.</p><h3 id="_4-agent-software-application-markets" tabindex="-1">4. Agent software application markets <a class="header-anchor" href="#_4-agent-software-application-markets" aria-label="Permalink to &quot;4. Agent software application markets&quot;">​</a></h3><p>The document also proposes agent software application stores and skill-package repositories, with rules for listing reviews and operational management.</p><p>This is a consequential step. Agents, skills and components must be discoverable, installable, composable, updatable and tradable if an agent software ecosystem is to develop, instead of every project starting from scratch.</p><p>Together, these four layers form a complete chain:</p><blockquote><p>Execution frameworks provide the foundation; development platforms produce software; agent products enter real use cases; marketplaces distribute them; service providers handle delivery and operations.</p></blockquote><p><img src="'+p+'" alt="Execution frameworks, development platforms, agent products and distribution form an industry, with delivery and governance spanning the chain."></p><p><em>Figure 3. Execution frameworks, development platforms, agent products and distribution form an industry, with delivery and governance spanning the chain. Source: Relevant MIIT policy documents; compiled by the author.</em></p><h2 id="v-skills-are-formally-included-in-agent-software-markets-more-than-a-prompt-marketplace" tabindex="-1">V. Skills Are Formally Included in Agent Software Markets: More Than a Prompt Marketplace <a class="header-anchor" href="#v-skills-are-formally-included-in-agent-software-markets-more-than-a-prompt-marketplace" aria-label="Permalink to &quot;V. Skills Are Formally Included in Agent Software Markets: More Than a Prompt Marketplace&quot;">​</a></h2><p>Document No. 209 explicitly proposes repositories for skill packages, or Skills, and encourages developers to build high-quality specialist skills, knowledge bases and functional components for agents.</p><p>A skill may appear to be a packaged capability: organizing contracts, analyzing equipment faults, generating quotations or operating a business system. Once it enters an enterprise or an application marketplace, however, it cannot remain a few paragraphs of prompts.</p><p><strong>From an enterprise engineering perspective,</strong> a commercially usable skill package raises the following questions. They are the author&#39;s deductions from the proposed skill repositories, listing reviews and operational management, rather than requirements individually prescribed by the document:</p><ul><li>Who publishes it, and can that identity be trusted?</li><li>Which agents and execution environments can use it?</li><li>Which models, data and tools does it depend on?</li><li>What permissions can it receive?</li><li>How are versions upgraded and rolled back?</li><li>What external effects does execution produce?</li><li>Can it stop, recover or undo work after an error?</li><li>Who approves its listing, and who handles ongoing operations?</li><li>Are its intellectual property, data sources and security risks clear?</li></ul><p>A mature Skills market will therefore resemble a software-package ecosystem for agents. Capabilities are modular, dependencies and permissions are explicit, effects can be inspected, and versions and responsibility can be traced.</p><p>This also creates new specializations. Some firms will build general-purpose skills; others will provide industry knowledge packages, maintain internal enterprise repositories, review security and compatibility, or operate agent marketplaces for particular industries.</p><p>Many small AI firms may not need to train their own foundation model. They can instead package knowledge, tools and workflows around a valuable business process. This connects directly with the entrepreneurship plan&#39;s emphasis on agent developers, open-source contributors and small specialist businesses.</p><h2 id="vi-why-verifiable-behavior-could-be-the-dividing-line-for-industrial-agents" tabindex="-1">VI. Why Verifiable Behavior Could Be the Dividing Line for Industrial Agents <a class="header-anchor" href="#vi-why-verifiable-behavior-could-be-the-dividing-line-for-industrial-agents" aria-label="Permalink to &quot;VI. Why Verifiable Behavior Could Be the Dividing Line for Industrial Agents&quot;">​</a></h2><p>In its provisions for industrial agents, the plan calls for safety, reliability and verifiable behavior.</p><p>The final requirement is easy to overlook, yet it may determine whether agents can enter actual production and business processes.</p><p>When a chatbot says something wrong, a user can often ignore or correct it. If an industrial agent changes production schedules, operates equipment, adjusts parameters, writes to a business system or triggers procurement, an error can become a real loss. A chat history alone cannot prove what happened or whether the result stayed within authorization.</p><p><strong>From an enterprise engineering perspective,</strong> the author breaks verifiable behavior into the following questions. This is an analytical framework, not an acceptance standard itemized in the document:</p><ul><li>What task did the agent receive?</li><li>Who authorized execution?</li><li>Which tools did it call?</li><li>What effects did those tools actually produce?</li><li>Did the results meet the business objective?</li><li>Who has authority to accept results and resolve disputes?</li><li>Did recovery repeat external effects whose status was unknown?</li></ul><p>A model&#39;s account of its own behavior cannot answer all these questions. Model output can contribute evidence, but does not automatically establish facts. Software can inspect files, states, hashes and tool results, but cannot assume the business owner&#39;s authority to judge whether the result is acceptable.</p><p>Industrial agents therefore need more than higher model accuracy. They need task agreements, identity and authorization, execution records, evidence of effects, independent verification and recovery mechanisms. Providers that turn these engineering capabilities into affordable, integrable infrastructure can help agents move from convincing demonstrations to systems that enterprises can actually trust to use.</p><p><img src="'+u+'" alt="Verifiable behavior separates task, authority, execution, effects and acceptance; recovery also requires state and side-effect checks."></p><p><em>Figure 4. Verifiable behavior separates task, authority, execution, effects and acceptance; recovery also requires state and side-effect checks. Source: Relevant MIIT policy documents; compiled by the author.</em></p><h2 id="vii-four-main-directions-for-agent-standards" tabindex="-1">VII. Four Main Directions for Agent Standards <a class="header-anchor" href="#vii-four-main-directions-for-agent-standards" aria-label="Permalink to &quot;VII. Four Main Directions for Agent Standards&quot;">​</a></h2><p>Document No. 209 does not announce a completed set of national agent standards. It commissions and advances subsequent standards development. That distinction matters.</p><p>The document proposes:</p><ul><li>Graded maturity assessment standards for intelligent programming capabilities.</li><li>Agent interface standards supporting hardware–software coordination.</li><li>Research into intelligent service standards, including Model as a Service and Agent as a Service.</li><li>Research into agent identity, trusted interconnection, data security and behavior control.</li><li>Security management requirements covering agent development, deployment and application.</li></ul><p>These provisions suggest four main directions.</p><p>The first is <strong>capability standards</strong>: how broad a task can a coding tool or development platform complete, and how should maturity be classified? Vendor claims are insufficient.</p><p>The second is <strong>interface standards</strong>: how should different models, devices, hardware, software systems and agents connect, without locking every capability into a single platform?</p><p>The third is <strong>service standards</strong>: how should MaaS and AaaS define scope, quality, measurement, responsibility and requirements for ongoing operations?</p><p>The fourth is <strong>governance standards</strong>: under what identity does an agent enter a system, how does it obtain permission, how can it connect trustworthily, and how are data and behavior protected, recorded and controlled?</p><p>The direction is now clear, but standards are still taking shape. The most useful work companies can do is accumulate real execution evidence, interface experience, security mechanisms and failure cases that can support standards development and pilot validation. Claiming compliance with unpublished national standards is premature.</p><h2 id="viii-open-source-as-a-mechanism-for-discovery-validation-and-diffusion" tabindex="-1">VIII. Open Source as a Mechanism for Discovery, Validation and Diffusion <a class="header-anchor" href="#viii-open-source-as-a-mechanism-for-discovery-validation-and-diffusion" aria-label="Permalink to &quot;VIII. Open Source as a Mechanism for Discovery, Validation and Diffusion&quot;">​</a></h2><p>The plan makes collaborative open-source innovation part of the foundation for intelligent software development. It calls for nationwide open-source foundations and AI communities to encourage firms to release work on intelligent programming, intelligent software products and agents. It supports first releases of key projects through communities, greater use of domestically developed open-source licenses and compliance guidance, and mechanisms for selecting and cultivating high-quality projects.</p><p>One particularly notable proposal is to explore open-source contributions as a reference for identifying promising software SMEs.</p><p>This echoes the entrepreneurship plan&#39;s use of public indicators such as project stars to identify high-growth potential. Document No. 209 goes further: open-source activity should help identify firms, while strong projects should also enter actual manufacturing, finance and other industry applications.</p><p>That could change how agent infrastructure projects develop.</p><p>A project once viewed primarily as a technical community contribution may become an entry point for policy support, industrial validation, service-provider partnerships and deployment. But visible code must become usable capability: clear installation instructions, stable interfaces, traceable versions, compliant licensing, reproducible tests and evidence of real use.</p><p>Stars increase visibility, but do not establish reliability. Publishing code alone does not establish industrial capability. The policy seeks projects that can participate in real software production and industry applications.</p><h2 id="ix-funding-projects-and-use-cases-direction-is-clear-applications-are-still-to-come" tabindex="-1">IX. Funding, Projects and Use Cases: Direction Is Clear, Applications Are Still to Come <a class="header-anchor" href="#ix-funding-projects-and-use-cases-direction-is-clear-applications-are-still-to-come" aria-label="Permalink to &quot;IX. Funding, Projects and Use Cases: Direction Is Clear, Applications Are Still to Come&quot;">​</a></h2><p>In its implementation provisions, Document No. 209 proposes mechanisms such as challenge-based project selection, coordination of funding channels and first-version software product recognition policies, support for eligible projects, and dedicated fiscal funding for key technology research, infrastructure and practical applications.</p><p>This creates the prospect of projects, pilots, standards work, adaptation centers, benchmark applications and local support measures.</p><p>The plan&#39;s computing-service provisions already call for <strong>compute vouchers and other broadly accessible support policies</strong> to reduce software companies&#39; computing costs. <a href="https://www.miit.gov.cn/jgsj/xxjsfzs/gzdt/art/2026/art_45df9463e105446c996568f299e07bca.html" target="_blank" rel="noreferrer">MIIT&#39;s official explanation</a> goes further: local authorities are encouraged to use compute vouchers and related policies to cover a proportion of the costs of purchasing domestically developed programming tools and using programming services from domestically developed large models. Support is therefore not confined to major projects; the policy also points toward assistance with companies&#39; purchases of intelligent programming tools and model services.</p><p>Policy direction must nevertheless be distinguished from an entitlement already granted.</p><p>Neither the plan nor this explanation sets a nationwide subsidy percentage, claim requirements or implementation timetable. They also do not publish unified project application dates, company eligibility rules, scoring criteria, funding pools or award amounts per project. Words such as support, encourage and explore do not mean every relevant company automatically receives a subsidy. Eligibility, covered expenses and payment timing remain subject to local policies and application notices.</p><p>Companies should prepare five kinds of material:</p><ol><li>Reproducible product capabilities and clear technical limits.</li><li>Real customer use cases and evidence of outcomes.</li><li>Complete development, testing, deployment and operating processes.</li><li>Explanations of data, permissions, security and intellectual property.</li><li>Demonstration cases that can be replicated, extended and inspected by third parties.</li></ol><p>When applications open, the strongest teams will be those that can demonstrate solutions to the engineering problems identified by the plan.</p><h2 id="x-the-new-software-value-chain-taking-shape" tabindex="-1">X. The New Software Value Chain Taking Shape <a class="header-anchor" href="#x-the-new-software-value-chain-taking-shape" aria-label="Permalink to &quot;X. The New Software Value Chain Taking Shape&quot;">​</a></h2><p>Document No. 209 covers far more participants than foundation-model companies. Its provisions point toward a new value chain:</p><p><img src="'+h+'" alt="Eight specializations in the agent software value chain and their core capabilities."></p><p><em>Figure 5. Eight specializations in the agent software value chain and their core capabilities. Source: Author&#39;s analysis of MIIT Document No. 209.</em></p><p>Not every company needs to build an all-encompassing agent platform. Specialist strengths in execution, skills, evaluation, security, integration or a particular industry can support independent businesses.</p><p>This is especially relevant to SMEs. They may struggle to compete with large firms in general-purpose foundation models, but can build advantages in data, processes, knowledge and delivery around a narrow, demanding use case. An agent that reliably handles procurement inquiries, equipment-fault analysis, research-document organization, quality tracking or export-customer management may have more commercial value than a feature-rich general assistant that cannot enter real operations.</p><h2 id="xi-competition-will-turn-to-what-ai-actually-achieves" tabindex="-1">XI. Competition Will Turn to What AI Actually Achieves <a class="header-anchor" href="#xi-competition-will-turn-to-what-ai-actually-achieves" aria-label="Permalink to &quot;XI. Competition Will Turn to What AI Actually Achieves&quot;">​</a></h2><p>The provisions on intelligent upgrading in software companies identify code quality and development effectiveness as important measures of intelligent programming adoption. This directly affects how companies should approach AI.</p><p>Connecting a foundation model will increasingly be insufficient as evidence of progress. Companies will need to answer:</p><ul><li>How much shorter is the delivery cycle?</li><li>Have defect rates fallen?</li><li>Are security issues detected earlier?</li><li>Have test coverage and maintenance efficiency improved?</li><li>Can complex projects progress through completion?</li><li>Do workflows remain stable after models or tools change?</li><li>How are jobs redesigned, rather than simply eliminated?</li></ul><h3 id="an-often-overlooked-policy-signal-stabilize-jobs-expand-opportunities-and-support-transitions" tabindex="-1">An Often-Overlooked Policy Signal: Stabilize Jobs, Expand Opportunities and Support Transitions <a class="header-anchor" href="#an-often-overlooked-policy-signal-stabilize-jobs-expand-opportunities-and-support-transitions" aria-label="Permalink to &quot;An Often-Overlooked Policy Signal: Stabilize Jobs, Expand Opportunities and Support Transitions&quot;">​</a></h3><p><a href="https://www.miit.gov.cn/jgsj/xxjsfzs/gzdt/art/2026/art_45df9463e105446c996568f299e07bca.html" target="_blank" rel="noreferrer">MIIT&#39;s official explanation</a> addresses employment directly through three priorities:</p><ul><li><strong>Stabilize jobs:</strong> protect existing employment in software and prevent sudden, large-scale unemployment.</li><li><strong>Expand opportunities:</strong> use agent software and intelligent services to create employment opportunities, including new roles in code review and AI security.</li><li><strong>Support transitions:</strong> strengthen job training and help software workers move into higher-value roles.</li></ul><p>Document No. 209 consequently addresses technology and products alongside a practical question: <strong>what happens to people as AI transforms the software industry?</strong> It does not simply encourage replacing programmers with AI. As production is reorganized, the policy brings job redesign, skills training, new roles and assessments of employment effects into the same framework.</p><p>For companies implementing the changes, a transformation plan should address more than development efficiency and tool costs. It should explain which roles will change, how people will be trained and redeployed, who will take responsibility for code review and AI security, and how employment risks will be identified and managed. A reduction in manual steps alone is not a complete measure of successful transformation.</p><p>Mature transformation requires a renewed division of work: machines perform executable tasks at scale, while people retain responsibility for goals, boundaries, professional judgment, exceptions and final accountability.</p><h2 id="xii-how-different-software-firms-can-transform" tabindex="-1">XII. How Different Software Firms Can Transform <a class="header-anchor" href="#xii-how-different-software-firms-can-transform" aria-label="Permalink to &quot;XII. How Different Software Firms Can Transform&quot;">​</a></h2><p>Document No. 209 does not give every software company the same task of connecting a large language model. Firms have different customers, products, technologies and delivery models, so their starting points should differ. The right sequence is to <strong>identify what is worth preserving in the existing business, determine which work can be delegated to agents, and then decide which capabilities are missing.</strong></p><h3 id="_1-established-software-vendors-retain-the-business-foundation-and-add-task-performing-capabilities" tabindex="-1">1. Established software vendors: retain the business foundation and add task-performing capabilities <a class="header-anchor" href="#_1-established-software-vendors-retain-the-business-foundation-and-add-task-performing-capabilities" aria-label="Permalink to &quot;1. Established software vendors: retain the business foundation and add task-performing capabilities&quot;">​</a></h3><p>For companies with ERP, CRM, finance, collaboration or industry software, the most valuable assets often include business objects, permission systems, historical data and customer trust. A natural-language interface is no reason to discard those assets.</p><p>A more practical path starts with bounded tasks: detecting unusual orders, preparing customer follow-up recommendations, explaining business data, or drafting transactions for review. Agents should access existing systems through controlled interfaces, rather than bypassing permissions to modify databases directly.</p><p>The transformation is not simply replacing menus with a chat box. It is moving from users performing every step to users setting a goal and the system completing a task within authorized limits. Existing approval and accountability mechanisms should remain for consequential actions involving payments, contracts, inventory or commitments to customers.</p><h3 id="_2-project-providers-and-integrators-move-toward-reusable-products-and-ongoing-operations" tabindex="-1">2. Project providers and integrators: move toward reusable products and ongoing operations <a class="header-anchor" href="#_2-project-providers-and-integrators-move-toward-reusable-products-and-ongoing-operations" aria-label="Permalink to &quot;2. Project providers and integrators: move toward reusable products and ongoing operations&quot;">​</a></h3><p>These firms understand customer environments, business processes and system integration. Their advantage is knowing which problems matter, not necessarily training another foundation model.</p><p>They should look for recurring needs across existing projects and turn reusable knowledge, interfaces, skills and acceptance methods into product packages. They must distinguish standard delivery from customization, while including model updates, knowledge maintenance, incident handling, security checks and outcome reviews in ongoing service.</p><p>The business model also needs clear boundaries: what implementation fees, subscriptions or operating fees cover; which data the customer supplies; who handles exceptions; and how service is handed over when a contract ends. Outcome-based pricing may be possible where outcomes can be measured and responsibility attributed. Promising it before defining acceptance is premature.</p><h3 id="_3-tool-and-platform-companies-move-from-isolated-generation-to-verifiable-engineering" tabindex="-1">3. Tool and platform companies: move from isolated generation to verifiable engineering <a class="header-anchor" href="#_3-tool-and-platform-companies-move-from-isolated-generation-to-verifiable-engineering" aria-label="Permalink to &quot;3. Tool and platform companies: move from isolated generation to verifiable engineering&quot;">​</a></h3><p>For coding tools, development platforms, cloud services and execution-framework providers, competition shifts from generating a piece of code to advancing a project reliably and producing maintainable results.</p><p>Within their product boundaries, firms need to build or integrate version control, testing, security checks, deployment, persistent state, tool permissions, cost control and recovery. No platform must build every component itself, but dependencies, integration responsibilities and failure ownership must be clear.</p><p>Evaluation should return to real projects: are delivery time, defect rework, maintenance costs and human intervention improving? A demonstration or model benchmark can establish a limited capability, but cannot replace project-level delivery evidence.</p><h3 id="_4-specialist-software-smes-deepen-expertise-in-a-valuable-bounded-process" tabindex="-1">4. Specialist software SMEs: deepen expertise in a valuable, bounded process <a class="header-anchor" href="#_4-specialist-software-smes-deepen-expertise-in-a-valuable-bounded-process" aria-label="Permalink to &quot;4. Specialist software SMEs: deepen expertise in a valuable, bounded process&quot;">​</a></h3><p>Smaller firms need not treat a comprehensive general-purpose agent platform as the inevitable destination. More practical opportunities often lie in narrow but demanding work such as procurement inquiries, equipment-fault analysis, quality tracking or research-document processing.</p><p>They can use existing models and platforms to package domain knowledge, tool interfaces and procedures into specialist agents or Skills. What can be sold, however, is more than a prompt: it includes a defined scope, data requirements, permission boundaries, test examples, an upgrade method and a service commitment.</p><p>Productization depends on whether the capability can be reused across customers and whether deployment and maintenance costs remain manageable. If each customer requires substantial redevelopment, it must still be accounted for as project work. Using an agent does not automatically turn it into a software product.</p><p><img src="'+m+'" alt="Firms should choose transformation opportunities from their existing strengths and business boundaries, then address missing capabilities."></p><p><em>Figure 6. Firms should choose transformation opportunities from their existing strengths and business boundaries, then address missing capabilities. Source: Author&#39;s enterprise transformation analysis informed by Document No. 209.</em></p><p>This is a business analysis informed by the policy, not an official classification or a prescribed transformation route. A company can occupy several positions. The point is to identify a boundary within which it can create value, rather than relabel every existing product with policy terminology.</p><h2 id="xiii-making-transformation-work-from-one-use-case-to-continuous-delivery" tabindex="-1">XIII. Making Transformation Work: From One Use Case to Continuous Delivery <a class="header-anchor" href="#xiii-making-transformation-work-from-one-use-case-to-continuous-delivery" aria-label="Permalink to &quot;XIII. Making Transformation Work: From One Use Case to Continuous Delivery&quot;">​</a></h2><p>After choosing a direction, a company still needs to answer a practical question: what should it do first, and what evidence justifies further investment?</p><p>Transformation need not begin with replacing every system, buying models in bulk or establishing a large AI department. A more measured approach starts with a verifiable business task and proceeds through choosing a use case, piloting it, establishing a service and expanding reuse. The following is implementation advice, not a process or timetable prescribed by Document No. 209.</p><h3 id="step-1-select-the-use-case-and-establish-the-business-baseline" tabindex="-1">Step 1. Select the use case and establish the business baseline <a class="header-anchor" href="#step-1-select-the-use-case-and-establish-the-business-baseline" aria-label="Permalink to &quot;Step 1. Select the use case and establish the business baseline&quot;">​</a></h3><p>Prioritize work with genuine, recurring demand, relatively stable inputs and inspectable results. Confirm the rights to use the data, permission to access the necessary systems, and the ability to hand control back to a person when something goes wrong.</p><p>For example, start with organizing procurement inquiries and flagging exceptions, then consider drafting transactions for approval. Do not begin with automatic payments whose authorization boundaries are undefined.</p><p>Before the pilot, record processing time, volume, errors, rework, labor costs and the acceptance method, and assign a business owner. Otherwise it will be difficult to tell whether any improvement came from AI, a process redesign or additional human effort.</p><h3 id="step-2-pilot-within-controlled-boundaries-and-record-failures-as-well-as-successes" tabindex="-1">Step 2. Pilot within controlled boundaries and record failures as well as successes <a class="header-anchor" href="#step-2-pilot-within-controlled-boundaries-and-record-failures-as-well-as-successes" aria-label="Permalink to &quot;Step 2. Pilot within controlled boundaries and record failures as well as successes&quot;">​</a></h3><p>Agree on permitted data, tools, permission limits and human-intervention conditions before introducing the agent into the process. Begin with read-only access, recommendations or actions after human review, then expand the scope as evidence warrants.</p><p>Validation should include missing data, tool timeouts, expired permissions, model changes and duplicate requests. Can the system stop, notify, hand off to a person or recover safely? Operations with external effects need particular care: an absent success response is not proof that an operation did not execute.</p><p>Proceed only when quality, efficiency and controllability meet the previously agreed acceptance criteria. If they do not, narrow the use case, revise the approach or stop the pilot.</p><h3 id="step-3-establish-a-sustainable-service-and-reorganize-roles-and-costs" tabindex="-1">Step 3. Establish a sustainable service and reorganize roles and costs <a class="header-anchor" href="#step-3-establish-a-sustainable-service-and-reorganize-roles-and-costs" aria-label="Permalink to &quot;Step 3. Establish a sustainable service and reorganize roles and costs&quot;">​</a></h3><p>A successful technical pilot does not establish commercial readiness. Companies must also assign responsibility for model and knowledge updates, incident handling, permission changes and version rollback, and define how customers raise disputes and accept results.</p><p>Roles need to change accordingly. Business staff own goals and acceptance; engineers own interfaces, execution and recovery; security staff review consequential permissions and data boundaries. One person may hold several roles, but important authorization and acceptance decisions cannot become ownerless because AI performs the work. Training, necessary independent review and role-transition costs also belong in the investment calculation.</p><p>Account for the full cost of delivery. Model calls and compute are only part of it: data preparation, integration, human review, monitoring, incidents, upgrades and customer support must also be paid for. Only comparison with measurable customer benefits can establish whether subscriptions, implementation fees or operating fees are sustainable.</p><h3 id="step-4-expand-across-customers-and-use-cases-only-when-evidence-supports-it" tabindex="-1">Step 4. Expand across customers and use cases only when evidence supports it <a class="header-anchor" href="#step-4-expand-across-customers-and-use-cases-only-when-evidence-supports-it" aria-label="Permalink to &quot;Step 4. Expand across customers and use cases only when evidence supports it&quot;">​</a></h3><p>Before scaling, separate shared capabilities from industry- or customer-specific configuration and identify permissions requiring individual authorization. Installation packages, skill versions, compatibility documentation, test examples, service documentation and rollback plans should become part of delivery.</p><p>Success with one customer does not establish success with different data, models or business systems. New customers and environments require revalidation of critical assumptions; the first successful case is not a universal conclusion.</p><p>Further investment should depend jointly on reuse, customer benefit, service costs and risk. Persistent dependence on extensive human intervention, insufficient benefits to cover costs, or unresolved consequential side effects are reasons not to force expansion merely to catch a policy window.</p><p>Software transformation therefore comes down to three questions: <strong>Does the customer receive a verifiable improvement? Can the company deliver it sustainably? Do human accountability and risk boundaries remain clear?</strong></p><p><img src="'+g+'" alt="Establish a baseline, run a bounded pilot, and use evidence to justify ongoing service and broader reuse."></p><p><em>Figure 7. Establish a baseline, run a bounded pilot, and use evidence to justify ongoing service and broader reuse. Source: Author&#39;s enterprise transformation analysis informed by Document No. 209.</em></p><h2 id="xiv-five-common-misreadings" tabindex="-1">XIV. Five Common Misreadings <a class="header-anchor" href="#xiv-five-common-misreadings" aria-label="Permalink to &quot;XIV. Five Common Misreadings&quot;">​</a></h2><h3 id="misreading-1-the-government-will-subsidize-every-ai-software-company" tabindex="-1">Misreading 1: The government will subsidize every AI software company <a class="header-anchor" href="#misreading-1-the-government-will-subsidize-every-ai-software-company" aria-label="Permalink to &quot;Misreading 1: The government will subsidize every AI software company&quot;">​</a></h3><p>The plan discusses coordinated funding, first-version software policies and dedicated fiscal funds, but creates no universal subsidy entitlement. Specific support depends on later projects and local rules.</p><h3 id="misreading-2-connecting-a-large-model-completes-software-transformation" tabindex="-1">Misreading 2: Connecting a large model completes software transformation <a class="header-anchor" href="#misreading-2-connecting-a-large-model-completes-software-transformation" aria-label="Permalink to &quot;Misreading 2: Connecting a large model completes software transformation&quot;">​</a></h3><p>The policy looks at development effectiveness, code quality, product upgrading, service value and real applications. Calling a model is an input, not an outcome.</p><h3 id="misreading-3-an-agent-is-just-a-chat-interface" tabindex="-1">Misreading 3: An agent is just a chat interface <a class="header-anchor" href="#misreading-3-an-agent-is-just-a-chat-interface" aria-label="Permalink to &quot;Misreading 3: An agent is just a chat interface&quot;">​</a></h3><p>The document also addresses execution frameworks, complex tasks, multi-agent collaboration, development and operating toolchains, system integration and behavior verification. Its scope goes well beyond chatbots.</p><h3 id="misreading-4-a-skills-market-is-a-place-to-sell-prompts" tabindex="-1">Misreading 4: A Skills market is a place to sell prompts <a class="header-anchor" href="#misreading-4-a-skills-market-is-a-place-to-sell-prompts" aria-label="Permalink to &quot;Misreading 4: A Skills market is a place to sell prompts&quot;">​</a></h3><p>Enterprise skills need versions, interfaces, dependencies, permissions, security, review and ongoing operations. Without these conditions, they are unlikely to enter critical business systems.</p><h3 id="misreading-5-the-policy-already-supplies-unified-agent-standards" tabindex="-1">Misreading 5: The policy already supplies unified agent standards <a class="header-anchor" href="#misreading-5-the-policy-already-supplies-unified-agent-standards" aria-label="Permalink to &quot;Misreading 5: The policy already supplies unified agent standards&quot;">​</a></h3><p>The document initiates and advances standards development. Companies cannot present their own concepts as national standards or claim certification before such arrangements exist.</p><h2 id="xv-the-opportunity-software-as-a-continuously-working-organizational-capability" tabindex="-1">XV. The Opportunity: Software as a Continuously Working Organizational Capability <a class="header-anchor" href="#xv-the-opportunity-software-as-a-continuously-working-organizational-capability" aria-label="Permalink to &quot;XV. The Opportunity: Software as a Continuously Working Organizational Capability&quot;">​</a></h2><p>Traditional software helped people record information, execute commands and manage processes. Generative AI enabled software to understand natural language. Agents take it further: software can receive goals, use tools and complete successive tasks.</p><p>As those capabilities enter enterprises, purchasing decisions may change.</p><p>An enterprise may buy a digital capability that continually delivers results, rather than just another system account. It may add an intelligent working role to procurement, R&amp;D, sales, customer service, compliance or operations, rather than simply installing a feature set.</p><p>This helps explain why Document No. 209 discusses software production, agent products, intelligent services and the organization of employment together. It addresses a reconfiguration of software, services and work.</p><p>Models provide intelligence, but do not automatically establish a job. Tools enable actions, but do not establish accountability. Workflows provide a route, but do not replace business judgment. A functioning digital employee system must organize models, tools, skills, identity, responsibilities, authorization, collaboration, verification and recovery into something that can operate over time.</p><p>Document No. 209 therefore opens more than a market for AI-written software.</p><p>It also opens a market in which software becomes agents, agents enter organizations, and organizations reconfigure their productive capacity.</p><h2 id="conclusion-toward-an-agent-software-industry" tabindex="-1">Conclusion: Toward an Agent Software Industry <a class="header-anchor" href="#conclusion-toward-an-agent-software-industry" aria-label="Permalink to &quot;Conclusion: Toward an Agent Software Industry&quot;">​</a></h2><p>In 2025, the State Council&#39;s <a href="https://www.mee.gov.cn/zcwj/gwywj/202508/t20250827_1126207.shtml" target="_blank" rel="noreferrer">Opinion on Deepening the “AI Plus” Initiative</a> established the national direction for integrating AI across the economy and society.</p><p>In 2026, policy has moved progressively into implementation.</p><p>Document No. 414 organizes application service providers and addresses who delivers. The entrepreneurship support plan cultivates AI SMEs and addresses who innovates. Document No. 209 transforms the software industry itself: how software is produced, how it runs continuously, how products and markets develop, and how behavior is verified and governed.</p><p>Across Document No. 414, the entrepreneurship support plan and Document No. 209, policy attention is extending beyond model capabilities to application delivery, entrepreneurs, software products, ongoing services and industrial infrastructure.</p><p>For software firms, this policy path calls attention to upgrading existing software and development methods, cultivating agent products and specialist Skills, and incorporating ongoing operations, behavior verification and workforce transitions into delivery capabilities. Whether these opportunities become viable businesses still has to be demonstrated through products, customers and operating results.</p><p>Document No. 209 thus advances the question:</p><blockquote><p>Once agents truly become software, how does China intend to build an industry around them?</p></blockquote><hr><h2 id="main-sources" tabindex="-1">Main Sources <a class="header-anchor" href="#main-sources" aria-label="Permalink to &quot;Main Sources&quot;">​</a></h2><ol><li>Ministry of Industry and Information Technology: <a href="https://www.miit.gov.cn/jgsj/xxjsfzs/wjfb/art/2026/art_91a26793271e4c77aca49ecde4472999.html" target="_blank" rel="noreferrer">Notice Issuing the Implementation Plan for the “AI Plus Software” Special Action</a>, Gong Xin Bu Xin Fa [2026] No. 209, published September 11, 2026.</li><li>General Office of MIIT: <a href="https://www.miit.gov.cn/jgsj/kjs/wjfb/art/2026/art_331b6f1d28ad410aa9df711acf42dbfe.html" target="_blank" rel="noreferrer">Notice on the Special Action to Cultivate AI Application Service Providers</a>, Gong Xin Ting Ke Han [2026] No. 414, published August 31, 2026.</li><li>General Office of MIIT: <a href="https://www.miit.gov.cn/jgsj/qyj/wjfb/art/2026/art_86c400b4473849818629663a94a6d44b.html" target="_blank" rel="noreferrer">Artificial Intelligence SME Entrepreneurship Support Plan (2026–2028)</a>, Gong Xin Ting Qi Ye [2026] No. 31, published September 4, 2026.</li><li>State Council: <a href="https://www.mee.gov.cn/zcwj/gwywj/202508/t20250827_1126207.shtml" target="_blank" rel="noreferrer">Opinion on Deepening the “AI Plus” Initiative</a>, Guo Fa [2025] No. 11.</li><li>Digital Employee Workshop: <a href="https://joinwell52-ai.github.io/joinwell52/en/industry/2026-09-04-miit-414-ai-application-delivery" target="_blank" rel="noreferrer">MIIT Document No. 414 Explained: From Model Supply to Application Delivery</a>.</li><li>Digital Employee Workshop: <a href="https://joinwell52-ai.github.io/joinwell52/en/industry/2026-09-08-miit-ai-sme-support-plan" target="_blank" rel="noreferrer">MIIT&#39;s AI SME Entrepreneurship Support Plan Explained: An AI Startup Ecosystem Is Taking Shape</a>.</li><li>MIIT&#39;s Department of Information Technology Development: <a href="https://www.miit.gov.cn/jgsj/xxjsfzs/gzdt/art/2026/art_45df9463e105446c996568f299e07bca.html" target="_blank" rel="noreferrer">Seven Questions and an Infographic: Understanding the “AI Plus Software” Implementation Plan</a>, published September 11, 2026; see questions 3 and 6 in particular.</li></ol>',205))])}const T=o(f,[["render",w]]);export{A as __pageData,T as default};
